package util

import (
	"strings"
	"testing"
)

// Synthetic cross-language vectors generated by the Node oracle (server/src/util.ts).
// salt is fed as the ASCII bytes of its hex STRING; keylen 64; N=16384 r=8 p=1.
const (
	nodeScryptPw     = "correct horse battery staple"
	nodeScryptStored = "scrypt$000102030405060708090a0b0c0d0e0f$2d05cd998694307d09324d39091e7dc45d610b22758eed53785ff7350464575493564fea574b76976b7c97ba84a602b4c3cabfc988f8a9dec764aaf978f40d72"
	nodeScrypt2Pw    = "密码P@ssw0rd☃"
	nodeScrypt2Store = "scrypt$ffeeddccbbaa99887766554433221100$dd52cad54e59b66995a99b37fa67f2da0ed36d1f20f8fb7e6b2d1890d97996689f188c9e771626ebf6b7746c15d6c3fb9b2bac32127c525adab7ea0cf5b6d0c5"
)

func TestVerifyPasswordNodeVectors(t *testing.T) {
	if !VerifyPassword(nodeScryptPw, nodeScryptStored) {
		t.Fatal("Node scrypt vector (ascii) failed to verify")
	}
	if !VerifyPassword(nodeScrypt2Pw, nodeScrypt2Store) {
		t.Fatal("Node scrypt vector (unicode) failed to verify")
	}
	if VerifyPassword("wrong password", nodeScryptStored) {
		t.Fatal("wrong password accepted")
	}
	if VerifyPassword(nodeScryptPw+" ", nodeScryptStored) {
		t.Fatal("password with trailing space accepted (must not trim)")
	}
}

func TestHashPasswordRoundTrip(t *testing.T) {
	for _, pw := range []string{"", "a", "密码P@ssw0rd☃", strings.Repeat("x", 200)} {
		stored := HashPassword(pw)
		if !strings.HasPrefix(stored, "scrypt$") {
			t.Fatalf("bad prefix: %q", stored)
		}
		parts := strings.Split(stored, "$")
		if len(parts) != 3 || len(parts[1]) != 32 || len(parts[2]) != 128 {
			t.Fatalf("bad shape: %q", stored)
		}
		if !VerifyPassword(pw, stored) {
			t.Fatalf("round-trip failed for %q", pw)
		}
		if VerifyPassword(pw+"x", stored) {
			t.Fatalf("wrong password accepted for %q", pw)
		}
	}
	// Two hashes of the same password differ (random salt).
	if HashPassword("same") == HashPassword("same") {
		t.Fatal("salt not random")
	}
}

func TestVerifyPasswordMalformed(t *testing.T) {
	bad := []string{
		"", "scrypt", "scrypt$", "scrypt$$", "bcrypt$salt$hash",
		"scrypt$salt$nothex", "scrypt$$" + strings.Repeat("a", 128),
		"scrypt$" + strings.Repeat("a", 32) + "$",
	}
	for _, s := range bad {
		if VerifyPassword("anything", s) {
			t.Fatalf("malformed stored hash accepted: %q", s)
		}
	}
}

// Node session vector: secret + fixed future exp (2030-01-01T00:00:00Z).
const (
	nodeSessionSecret = "test-secret-abc-0123456789"
	nodeSessionToken  = "1893456000000.3-aOl32GnM2ymDe7hbFJQFPI7hRhEss2f6thzVvxIzE"
)

func TestVerifySessionNodeVector(t *testing.T) {
	if !VerifySession(nodeSessionToken, nodeSessionSecret) {
		t.Fatal("Node session token failed to verify")
	}
	if VerifySession(nodeSessionToken, "wrong-secret") {
		t.Fatal("token accepted with wrong secret")
	}
	// Tamper with the signature.
	tampered := nodeSessionToken[:len(nodeSessionToken)-1] + "X"
	if VerifySession(tampered, nodeSessionSecret) {
		t.Fatal("tampered token accepted")
	}
}

func TestSignVerifySession(t *testing.T) {
	secret := RandomToken(32)
	tok := SignSession(secret, 7*24*3600*1000)
	if !VerifySession(tok, secret) {
		t.Fatal("freshly signed token rejected")
	}
	if VerifySession(tok, RandomToken(32)) {
		t.Fatal("token accepted with different secret")
	}
	// Already expired.
	expired := SignSession(secret, -1000)
	if VerifySession(expired, secret) {
		t.Fatal("expired token accepted")
	}
}

func TestVerifySessionMalformed(t *testing.T) {
	secret := "s"
	bad := []string{"", ".", "abc", "abc.def", "0.sig", "-1.sig", "1893456000000", ".sig"}
	for _, tok := range bad {
		if VerifySession(tok, secret) {
			t.Fatalf("malformed token accepted: %q", tok)
		}
	}
}

func TestRandomShapes(t *testing.T) {
	if len(RandomId()) != 16 {
		t.Fatal("randomId length")
	}
	if len(RandomToken(32)) != 64 {
		t.Fatal("randomToken(32) length")
	}
	if len(RandomToken(24)) != 48 {
		t.Fatal("randomToken(24) length")
	}
	if RandomToken(32) == RandomToken(32) {
		t.Fatal("randomToken not random")
	}
}

func TestGeneratePassword(t *testing.T) {
	for _, n := range []int{1, 8, 16, 32} {
		pw := GeneratePassword(n)
		if len(pw) != n {
			t.Fatalf("generatePassword(%d) length = %d", n, len(pw))
		}
		for _, c := range pw {
			if !strings.ContainsRune(passwordAlphabet, c) {
				t.Fatalf("char %q outside alphabet", c)
			}
		}
	}
}
